/* Replaces the wolfssl/options.h generated by wolfSSL's CMake, which ignores user_settings.h and
 * lists CMake's default features instead (TLS 1.3, SHA-3, ML-KEM...). Applications such as curl
 * include it to check which features are enabled: give them the real configuration.
 * The wolfSSL library itself never includes this file. */

#include <wolfssl/wolfcrypt/settings.h>
